def to_minutes(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m


def to_time(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


days = ["Monday", "Tuesday", "Wednesday"]
work_start = to_minutes("09:00")
work_end = to_minutes("17:00")
duration = 30

busy = {
    "Joshua": {
        "Monday": [("15:00", "15:30")],
        "Tuesday": [
            ("11:30", "12:00"),
            ("13:00", "13:30"),
            ("14:30", "15:00"),
        ],
        "Wednesday": [],
    },
    "Joyce": {
        "Monday": [
            ("09:00", "09:30"),
            ("10:00", "11:00"),
            ("11:30", "12:30"),
            ("13:00", "15:00"),
            ("15:30", "17:00"),
        ],
        "Tuesday": [
            ("09:00", "17:00"),
        ],
        "Wednesday": [
            ("09:00", "09:30"),
            ("10:00", "11:00"),
            ("12:30", "15:30"),
            ("16:00", "16:30"),
        ],
    },
}

preferred_day = "Wednesday"


def is_free(day, start):
    end = start + duration
    if start < work_start or end > work_end:
        return False

    for schedule in busy.values():
        for busy_start, busy_end in schedule.get(day, []):
            bs = to_minutes(busy_start)
            be = to_minutes(busy_end)
            if start < be and end > bs:
                return False

    return True


def preference_penalty(day, start):
    penalty = 0
    if day != preferred_day:
        penalty += 1000
    if day == "Monday" and start < to_minutes("12:00"):
        penalty += 1
    return penalty


day_order = [preferred_day] + [d for d in days if d != preferred_day]
best = None

for day in day_order:
    day_rank = day_order.index(day)
    for start in range(work_start, work_end - duration + 1, 30):
        if not is_free(day, start):
            continue

        key = (preference_penalty(day, start), day_rank, start)
        if best is None or key < best[0]:
            best = (key, day, start)

if best is None:
    raise SystemExit("No feasible meeting time found")

_, day, start = best
print([day, to_time(start), to_time(start + duration)])

