        (to_minutes(12,0), to_minutes(12,30)),
        (to_minutes(13,0), to_minutes(14,0)),
        (to_minutes(14,30), to_minutes(16,0)),
        (to_minutes(16,30), to_minutes(17,0)),
    ],
}

john_busy = {day: [] for day in days}

def is_free(day, start, end, busy):
    for b_start, b_end in busy[day]:
        if start < b_end and end > b_start:
            return False
    return True

def allowed_by_john_preference(day, start):
    # John wants to avoid meetings after 14:30 on Monday, and on Tuesday/Wednesday.
    if day == "Monday" and start >= to_minutes(14, 30):
        return False
    if day in ("Tuesday", "Wednesday"):
